using System;
namespace LWS.TruckBakeOff {
 public enum BakeStage { Ingredients,Mixing,Mixed,Loaded,Baking,Cooked,Decorated,Presented,Failed }
 public enum BakeIngredient { Flour,Milk,Sugar,Egg }
 [Serializable]public sealed class BakeRules {
  public readonly float[,] measured=new float[4,4];public readonly float[] mixSeconds=new float[4],heatSeconds=new float[4],batter=new float[4],icing=new float[4];readonly float[,] quadrantCream=new float[4,4];public readonly int[] points=new int[4],decorated=new int[4];public readonly BakeStage[] stages=new BakeStage[4];public readonly bool[] failed=new bool[4];public static float Target(BakeIngredient ingredient)=>ingredient==BakeIngredient.Flour?.8f:ingredient==BakeIngredient.Milk?.5f:ingredient==BakeIngredient.Sugar?.3f:1;
  public int Count{get;private set;}public float Clock{get;private set;}public float Remaining{get;private set;}public bool Complete{get;private set;}public bool Active=>Clock>=3&&!Complete;float allDoneAt=-1;
  public void Reset(int count,int option){Count=Math.Clamp(count,1,4);Clock=0;Remaining=option==0?300:option==1?420:540;Complete=false;allDoneAt=-1;Array.Clear(measured,0,measured.Length);Array.Clear(mixSeconds,0,4);Array.Clear(heatSeconds,0,4);Array.Clear(batter,0,4);Array.Clear(icing,0,4);Array.Clear(quadrantCream,0,quadrantCream.Length);Array.Clear(points,0,4);Array.Clear(decorated,0,4);Array.Clear(failed,0,4);Array.Clear(stages,0,4);}
  public void Tick(float dt){if(Complete||!float.IsFinite(dt)||dt<=0)return;dt=Math.Min(dt,.1f);Clock+=dt;if(Clock<3)return;Remaining=Math.Max(0,Remaining-dt);bool done=true;for(int i=0;i<Count;i++)done&=stages[i]==BakeStage.Presented||stages[i]==BakeStage.Failed;if(done&&allDoneAt<0)allDoneAt=Clock;Complete=Remaining<=0||allDoneAt>=0&&Clock-allDoneAt>=5;}
  bool Slot(int slot)=>Active&&slot>=0&&slot<Count&&!failed[slot];
  public bool Measure(int slot,BakeIngredient kind,float actual){if(!Slot(slot)||stages[slot]>BakeStage.Mixing||!float.IsFinite(actual)||actual<=0||(int)kind<0||(int)kind>3)return false;measured[slot,(int)kind]+=Math.Min(actual,4);bool ready=true;for(int k=0;k<4;k++)ready&=measured[slot,k]>=Target((BakeIngredient)k)*.85f;if(ready)stages[slot]=BakeStage.Mixing;return true;}
  public bool Mix(int slot,float dt,bool nativeWhiskContact){if(!Slot(slot)||stages[slot]!=BakeStage.Mixing||!nativeWhiskContact||!float.IsFinite(dt)||dt<=0)return false;mixSeconds[slot]+=Math.Min(dt,.1f);if(mixSeconds[slot]>=8)stages[slot]=BakeStage.Mixed;return true;}
  public bool LoadPan(int slot,float actualBatter){if(!Slot(slot)||stages[slot]!=BakeStage.Mixed&&stages[slot]!=BakeStage.Loaded||!float.IsFinite(actualBatter)||actualBatter<=0)return false;batter[slot]+=Math.Min(actualBatter,4);if(batter[slot]>=2.1f)stages[slot]=BakeStage.Loaded;return true;}
  public bool Heat(int slot,float dt,float temperature,bool physicalInsideClosed){if(!Slot(slot)||stages[slot]<BakeStage.Loaded||stages[slot]>=BakeStage.Presented||!physicalInsideClosed||!float.IsFinite(dt)||!float.IsFinite(temperature)||dt<=0||temperature<150)return false;heatSeconds[slot]+=Math.Min(dt,.1f)*Math.Clamp((temperature-100)/100,0,1.3f);if(heatSeconds[slot]>=10){if(stages[slot]<BakeStage.Cooked)stages[slot]=BakeStage.Cooked;}else stages[slot]=BakeStage.Baking;return true;}
  public bool Decorate(int slot,int quadrant,float actualCream){if(!Slot(slot)||stages[slot]!=BakeStage.Cooked&&stages[slot]!=BakeStage.Decorated||quadrant<0||quadrant>3||!float.IsFinite(actualCream)||actualCream<.005f)return false;icing[slot]+=Math.Min(actualCream,.2f);quadrantCream[slot,quadrant]+=Math.Min(actualCream,.2f);if(quadrantCream[slot,quadrant]>=.04f)decorated[slot]|=1<<quadrant;if(decorated[slot]==15)stages[slot]=BakeStage.Decorated;return true;}
  public int Judge(int slot,bool actualSettled,bool intact,float retainedCake){if(!Slot(slot)||stages[slot]!=BakeStage.Decorated||!actualSettled||!intact||!float.IsFinite(retainedCake)||retainedCake<1.8f)return 0;float error=0;for(int i=0;i<4;i++)error+=Math.Min(1,Math.Abs(measured[slot,i]-Target((BakeIngredient)i))/Target((BakeIngredient)i));float recipe=1-error*.25f;float cooking=Math.Clamp(1-Math.Max(0,heatSeconds[slot]-18)/15,.1f,1);int score=50+(int)Math.Round(recipe*120+cooking*80+Math.Min(1,icing[slot]/.16f)*30+20);points[slot]=score;stages[slot]=BakeStage.Presented;return score;}
  public void Fail(int slot){if(!Slot(slot)||stages[slot]==BakeStage.Presented)return;failed[slot]=true;stages[slot]=BakeStage.Failed;}
  public int Place(int slot){int place=1;for(int i=0;i<Count;i++)if(points[i]>points[slot])place++;return place;}
 }
}
